venmo__show_transactions.program:
goal = state["instruction"]
received = regex(r"\b(?:payments?|transactions?)\b.{0,40}\b(?:received|incoming)\b|\breceived\b.{0,30}\b(?:payments?|transactions?)\b", goal)
sent = regex(r"\b(?:payments?|transactions?)\b.{0,40}\b(?:sent|outgoing)\b|\bsent\b.{0,30}\b(?:payments?|transactions?)\b", goal)
if received == sent:
    return None
args = {"direction": "received" if received else "sent"}
days = captures(r"\b(?:last|past)\s+(\d+)\s+days?\b", state["instruction"])
if len(days) == 1 and regex(r"\bincluding today\b", state["instruction"]):
    args["min_created_at"] = first_calendar_day(state["datetime"], int(days[0]))
return [args]

phone__search_contacts.program:
groups = captures(r"\b(coworkers?|colleagues?|roommates?|housemates?|friends?|managers?|siblings?)\b", state["instruction"])
labels = {"colleague": "coworker", "housemate": "roommate"}
roles = set()
for group in groups:
    name = group.lower()
    singular = name[:-1] if name.endswith("s") else name
    roles.add(labels.get(singular, singular))
if len(roles) != 1:
    return None
return [{"relationship": list(roles)[0]}]

venmo__create_transaction_comment.program:
if not state['complete'] or not state['rows']:
    return None
parts = captures(r'\b(?:add|post|leave|write)\s+(?:a\s+)?comment\s*[:,]?\s*(?:"([^"\n]+)"|“([^”\n]+)”)\s*,?\s+(?:on|to|for)\s+(?:all(?:\s+of)?(?:\s+the)?|each|every)\s+venmo\s+(?:payments?|transactions?)\b', state['instruction'])
if len(parts) != 1:
    return None
comment = parts[0][0] or parts[0][1]
if not comment.strip():
    return None
return [{'transaction_id': row['transaction_id'], 'comment': comment} for row in state['rows']]

venmo__like_transaction.program:
if not state['complete'] or not state['rows']:
    return None
goal = state['instruction']
for quoted in captures(r'"[^"]*"|“[^”]*”', goal):
    goal = goal.replace(quoted, ' ')
direct = regex(r'\blike\s+(?:all(?:\s+of)?(?:\s+the)?|each|every)\s+venmo\s+(?:payments?|transactions?)\b', goal)
reference = regex(r'\b(?:and|then|also)\s+(?:also\s+)?like\s+(?:all\s+(?:of\s+)?|each\s+of\s+)?(?:those|these|the)\s+(?:payments?|transactions?)(?:\s+(?:too|as\s+well))?\s*[.!?]?\s*$', goal)
if not (direct or reference):
    return None
return [{'transaction_id': row['transaction_id']} for row in state['rows']]

