playlist_genre_follow_targets.program:
genres = captures(r"\b([a-z0-9&-]+)[ -]genre\s+(?:songs?|tracks?)\b", state["instruction"])
if len(genres) != 1 or not regex(r"\b(?:my\s+(?:spotify\s+)?playlists|playlists\s+(?:that\s+)?i\s+own)\b", state["instruction"]):
    return None
if regex(r"\b(?:except|unless|excluding|without|never)\b", state["instruction"]):
    return None
wanted = genres[0].casefold()
tracks = state["inputs"]["spotify__show_song"]["rows"]
followed = state["inputs"]["spotify__show_following_artists"]["rows"]
current = set()
for row in followed:
    artist_id = row.get("artist_id", row.get("id"))
    if not isinstance(artist_id, int):
        return None
    current.add(artist_id)
targets = set()
for track in tracks:
    if not isinstance(track.get("genre"), str):
        return None
    if track["genre"].casefold() != wanted:
        continue
    artists = track.get("artists")
    if not isinstance(artists, list):
        return None
    for artist in artists:
        artist_id = artist.get("id")
        if not isinstance(artist_id, int):
            return None
        if artist_id not in current:
            targets.add(artist_id)
return [{"artist_id": artist_id} for artist_id in sorted(targets)]

reads.phone__search_contacts:
goal = state["goal"]
if not regex(r"\bpending\s+(?:venmo\s+)?payment\s+requests?\b", goal) or not regex(r"\bvenmo\b", goal):
    return None
groups = captures(r"\bfrom\s+(?:any\s+of\s+)?my\s+([a-z, -]+?)[.!?]?\s*$", goal)
if len(groups) != 1:
    return None
aliases = {"colleague": "coworker", "housemate": "roommate"}
known = {"coworker", "friend", "roommate", "sibling", "parent", "father", "mother", "manager", "brother", "sister"}
roles = set()
for word in groups[0].replace(",", " ").replace("co-worker", "coworker").split():
    if word in ("and", "or"):
        continue
    singular = word[:-1] if word.endswith("s") else word
    role = aliases.get(singular, singular)
    if role not in known:
        return None
    roles.add(role)
return [{"relationship": role} for role in sorted(roles)]

pending_requests_by_contact_group.program:
queries = state["arguments"]
contacts = state["rows"] if len(queries) == 1 else [r for group in state["rows"] for r in group]
emails = set()
for row in contacts:
    email = row.get("email")
    if not isinstance(email, str) or not email.strip():
        return None
    emails.add(email.strip().casefold())
pending = state["inputs"]["venmo__show_received_payment_requests"]
if pending.get("arguments") != [{"status": "pending"}]:
    return None
targets = set()
for row in pending["rows"]:
    sender = row.get("sender", {}).get("email")
    request_id = row.get("payment_request_id")
    if not isinstance(sender, str) or not isinstance(request_id, int):
        return None
    if sender.strip().casefold() in emails:
        targets.add(request_id)
return [{"payment_request_id": request_id} for request_id in sorted(targets)]

reads.phone__search_contacts:
goal = state['instruction']
for quoted in captures(r'"[^"]*"|“[^”]*”', goal):
    goal = goal.replace(quoted, ' ')
groups = captures(r'\breceived\s+from\s+my\s+(co-?workers?|colleagues?|friends?|roommates?|housemates?)\s+(?:in|over|within|during)\s+(?:the\s+)?(?:last|past)\b', goal)
if len(groups) != 1 or not regex(r'\bvenmo\b', goal):
    return None
role = groups[0].casefold().replace('-', '')
if role.endswith('s'):
    role = role[:-1]
return [{'relationship': {'colleague': 'coworker', 'housemate': 'roommate'}.get(role, role)}]

received_payments_from_contact_group.program:
goal = state['instruction']
for quoted in captures(r'"[^"]*"|“[^”]*”', goal):
    goal = goal.replace(quoted, ' ')
intro = r'\b(?:all(?:\s+of)?(?:\s+the)?|each|every)\s+venmo\s+(?:payments?|transactions?)\b'
if not state['complete'] or len(captures(intro, goal)) != 1 or regex(r"\b(?:not|don['’]t|never|except|excluding|unless)\b", goal):
    return None
matches = captures(intro + r"\s+(?:(?:that|which)\s+)?(?:(?:i(?:\s+have)?|i['’]ve|were)\s+)?received\s+from\s+my\s+(co-?workers?|colleagues?|friends?|roommates?|housemates?)\s+(?:in|over|within|during)\s+(?:the\s+)?(?:last|past)\s+([1-9]\d*)\s+days?\s*(?:\(\s*including\s+today\s*\)|,?\s*including\s+today\b)(?=\s*(?:[.!?]?\s*$|[,;]?\s*(?:and|then|also)\b))", goal)
if len(matches) != 1:
    return None
role, days = matches[0]
role = role.casefold().replace('-', '')
if role.endswith('s'):
    role = role[:-1]
role = {'colleague': 'coworker', 'housemate': 'roommate'}.get(role, role)
start = first_calendar_day(state['datetime'], int(days))
today = first_calendar_day(state['datetime'], 1)
expected = [{'direction': 'received', 'min_created_at': start}]
if state.get('arguments') != expected:
    return None
contacts = state['inputs'].get('phone__search_contacts')
if not contacts or not contacts['complete']:
    return None
if contacts.get('arguments') != [{'relationship': role}]:
    return None
emails = set()
for row in contacts['rows']:
    relationships = row.get('relationships')
    email = row.get('email')
    if not isinstance(relationships, list) or role not in relationships or not isinstance(email, str) or not email.strip():
        return None
    emails.add(email.strip().casefold())
seen = set()
result = []
for row in state['rows']:
    created = row.get('created_at')
    if not isinstance(created, str):
        return None
    if not start <= created[:10] <= today:
        continue
    sender = row.get('sender')
    if not isinstance(sender, dict) or not isinstance(sender.get('email'), str) or not sender['email'].strip():
        return None
    if sender['email'].strip().casefold() not in emails:
        continue
    transaction_id = row.get('transaction_id')
    if not isinstance(transaction_id, int):
        return None
    if transaction_id not in seen:
        seen.add(transaction_id)
        result.append(row)
return result

explicit_effects.program:
goal = state["instruction"]
effects = []
if regex(r"\bsimple note\b", goal) and regex(r"\b(mark|update|edit|change)\b", goal):
    effects.append("simple_note__update_note")
if regex(r"\bvenmo\b", goal) and regex(r"\b(payments?|transactions?)\b", goal):
    if regex(r"\b(add|post|leave|write)\s+(?:a\s+)?comment\b", goal):
        effects.append("venmo__create_transaction_comment")
    if regex(r"\blike\s+(?:all\s+)?(?:those|the|these|each)\s+(?:payments?|transactions?)\b", goal):
        effects.append("venmo__like_transaction")
return effects

